// Compiler hint to unroll
#pragma unroll
for (int i = 0; i < 4; i++) {
    sum += a[i] * b[i];
}

// Fully unrolled to:
// sum += a[0]*b[0] + a[1]*b[1] + a[2]*b[2] + a[3]*b[3];
```

